def get_grade(threshold):
    """
    Prompts the user to enter a score and returns their grade based on the given threshold.

    :param threshold: The minimum score required to pass.
    :return: The user's grade (string).
    """
    while True:
        try:
            score = float(input("Enter your score: "))
            if score >= threshold:
                return f"A"
            elif score >= (threshold - 10) / 2:
                return f"B"
            elif score >= (threshold - 20) / 2:
                return f"C"
            elif score >= (threshold - 30) / 2:
                return f"D"
            else:
                return f"F"
        except ValueError:
            print("Invalid input. Please enter a number.")

